head.b:skin:
/* --- SYSTEM RESET --- */
body {
  background-color: #0d0f12;
  color: #e2e8f0;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  margin: 0;
  padding: 0;
}
a {
  text-decoration: none;
  color: #38bdf8;
  transition: 0.2s ease-in-out;
}
a:hover {
  color: #f97316;
}

/* --- 1. DYNAMIC TOP CATEGORIES ROW --- */
.top-category-bar {
  background-color: #0b0c10;
  padding: 10px 20px;
  border-bottom: 2px solid #1a1d24;
  display: flex;
  align-items: center;
  gap: 16px;
}
#top-categories {
  flex: 1;
  min-width: 0;
}
.top-category-bar ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  gap: 20px;
  overflow-x: auto;
  white-space: nowrap;
}
.top-category-bar ul li a {
  font-size: 13px;
  color: #94a3b8;
  font-weight: 700;
  text-transform: uppercase;
}
.top-category-bar ul li a:hover {
  color: #38bdf8;
}

/* --- 1b. YEAR FILTER DROPDOWN --- */
#top-categories-year {
  flex-shrink: 0;
}
.year-filter {
  position: relative;
}
.year-filter summary {
  list-style: none;
  cursor: pointer;
  font-size: 13px;
  color: #94a3b8;
  font-weight: 700;
  text-transform: uppercase;
  padding: 4px 2px;
  user-select: none;
  white-space: nowrap;
}
.year-filter summary::-webkit-details-marker {
  display: none;
}
.year-filter summary::after {
  content: ' \25BE';
  font-size: 11px;
  margin-left: 4px;
  color: #f97316;
}
.year-filter[open] summary::after {
  content: ' \25B4';
}
.year-filter summary:hover {
  color: #38bdf8;
}
.year-filter ul {
  list-style: none;
  margin: 8px 0 0 0;
  padding: 6px 0;
  position: absolute;
  top: 100%;
  right: 0;
  min-width: 110px;
  background-color: #1a1d24;
  border: 1px solid #2a2e37;
  border-radius: 6px;
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
  z-index: 2000;
  display: flex;
  flex-direction: column;
}
.year-filter ul li {
  white-space: nowrap;
}
.year-filter ul li a {
  display: block;
  padding: 8px 16px;
  font-size: 13px;
  color: #94a3b8;
  font-weight: 600;
  text-transform: none;
}
.year-filter ul li a:hover {
  color: #38bdf8;
  background-color: #23262e;
}
@media (max-width: 480px) {
  .year-filter ul {
    right: auto;
    left: 0;
  }
}

/* --- 2. MAIN HEADER & LOGO --- */
header {
  background-color: #1a1d24;
  padding: 15px 20px 5px 20px;
  display: flex;
  flex-direction: column;
  border-bottom: 2px solid #f97316;
  position: sticky;
  top: 0;
  z-index: 1000;
}
.logo-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}
.logo a {
  font-size: 26px;
  font-weight: 800;
  color: #f97316;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.logo span {
  color: #e2e8f0;
}

/* --- 3. DYNAMIC PAGES ROW --- */
.pages-menu ul {
  list-style: none;
  padding: 0;
  margin: 0 0 10px 0;
  display: flex;
  gap: 20px;
  overflow-x: auto;
}
.pages-menu ul li a {
  font-size: 14px;
  color: #e2e8f0;
  font-weight: 600;
}
.pages-menu ul li a:hover {
  color: #f97316;
}

/* --- MAIN CONTAINER --- */
.container {
  max-width: 1200px;
  margin: 30px auto;
  padding: 0 15px;
}
.section-title {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 20px;
  border-left: 4px solid #f97316;
  padding-left: 10px;
  text-transform: uppercase;
}

/* --- BLOG GRID (Desktop: Autofill, Mobile: Exactly 2 Columns) --- */
.post-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 15px;
}
.anime-card {
  background-color: #1a1d24;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid #2e3440;
  transition: transform 0.3s ease, border-color 0.3s ease;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
}
.anime-card:hover {
  transform: translateY(-5px);
  border-color: #f97316;
}
.card-thumbnail {
  width: 100%;
  height: 240px;
  object-fit: cover;
  background-color: #2d3748;
}
.card-info {
  padding: 10px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  flex-grow: 1;
}
.card-title {
  font-size: 13px;
  font-weight: 600;
  margin: 0 0 8px 0;
  line-height: 1.4;
  height: 36px;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.download-btn {
  display: block;
  text-align: center;
  background: linear-gradient(135deg, #f97316, #ea580c);
  color: #fff;
  padding: 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}
.download-btn:hover {
  background: #38bdf8;
  color: #0d0f12;
}

/* --- MOBILE SPECIFIC: FORCE 2 POSTS PER ROW --- */
@media screen and (max-width: 600px) {
  .post-grid {
    grid-template-columns: repeat(2, 1fr) !important;
    gap: 10px !important;
  }
  .card-thumbnail {
    height: 200px !important;
  }
  .card-title {
    font-size: 12px !important;
  }
  .post-body-single img {
    max-height: 340px;
  }
}

/* --- SINGLE POST PAGE REDESIGN --- */
.single-post {
  background-color: #1a1d24;
  padding: 25px;
  border-radius: 8px;
  border: 1px solid #2e3440;
}
.post-title-single {
  font-size: 28px;
  color: #f97316;
  margin-top: 0;
  margin-bottom: 20px;
  font-weight: 800;
  line-height: 1.3;
}
.post-body-single {
  font-size: 16px;
  line-height: 1.6;
  color: #e2e8f0;
}

/* Post Images Auto-Center & Scale nicely */
.post-body-single img {
  max-width: 100% !important;
  max-height: 480px;
  width: auto;
  height: auto !important;
  object-fit: contain;
  border-radius: 8px;
  margin: 15px auto;
  display: block;
}

/* Custom Styled Tables for Anime/Movie Info */
.post-body-single table {
  width: 100% !important;
  border-collapse: collapse;
  margin: 25px 0;
  background-color: #111318;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid #2e3440;
}
.post-body-single th, .post-body-single td {
  padding: 12px 15px;
  border-bottom: 1px solid #2e3440;
  text-align: left;
}
.post-body-single th {
  background-color: #f97316;
  color: #ffffff;
  font-weight: 700;
  text-transform: uppercase;
}
.post-body-single tr:last-child td {
  border-bottom: none;
}

/* Quality Badges & Season Headers */
.post-body-single h3 {
  color: #f97316;
  border-bottom: 1px solid #2e3440;
  padding-bottom: 5px;
  margin-top: 30px;
}
.post-body-single ul {
  padding-left: 20px;
}
.post-body-single li {
  margin-bottom: 8px;
}

/* --- FOOTER --- */
footer {
  background-color: #1a1d24;
  text-align: center;
  padding: 20px;
  margin-top: 50px;
  border-top: 1px solid #2e3440;
  font-size: 13px;
  color: #64748b;
}

/* --- HIDE LEFTOVER/ORPHANED GADGETS (Archive, Labels, Search) ---
   These aren't part of the custom design. This hides them wherever
   Blogger tries to render them, so single-post pages stay clean. */
.BlogArchive, .Label, .LabelSearch, .BlogSearch, .Attribution,
[id^="BlogArchive"], [id^="Label"], [id^="BlogSearch"] {
  display: none !important;
}

/* --- NEW: AD PLACEMENT SLOTS (additive only, no existing rules modified) --- */
.ad-slot {
  margin: 20px 0;
  text-align: center;
}

head.script:
var app_url = 'https://shrinkme.io/';
var app_api_token = 'd32b71d07578d9ce3890289b534df874a8b3821b';
var app_advert = 2;
var app_exclude_domains = ["*.blogspot.com","*.blogspot.*","blogger.com"];

//
window.addEventListener("load", function() {
    // Target common Blogger content wrappers
    var postBody = document.querySelector('.post-body-single, .post-body, .entry-content, .post-content');
    if (postBody) {
        var html = postBody.innerHTML;

        // This loose regex safely captures the URL and button text no matter what extra tags Blogger adds
        var regex = /<a\s+[^>]*href=["']([^"']*)["'][^>]*>\s*_{getProduct}\s+\$button={(.*?)}\s*<\/a>/gi;

        var newHtml = html.replace(regex, function(match, linkUrl, btnText) {
            return '<div style="background:#111217; border:1px solid #1a1d24; border-radius:10px; padding:20px; max-width:450px; margin:25px auto; text-align:center; box-shadow:0 10px 25px rgba(0,0,0,0.5); font-family:Arial,sans-serif; clear:both;">' +
                   '  <a href="' + linkUrl + '" target="_blank" style="display:block; background:#f97316; color:#ffffff !important; text-decoration:none !important; padding:14px; font-size:16px; font-weight:bold; border-radius:8px; box-shadow:0 4px 15px rgba(249, 115, 22, 0.3); transition:all 0.2s ease-in-out;" ' +
                   '     onmouseover="this.style.background=\'#ea580c\'; this.style.transform=\'translateY(-2px)\';"' +
                   '     onmouseout="this.style.background=\'#f97316\'; this.style.transform=\'translateY(0)\';">' +
                   '    📥 ' + btnText + 
                   '  </a>' +
                   '</div>';
        });

        postBody.innerHTML = newHtml;
    }
});
//

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
document.addEventListener("DOMContentLoaded", function() {
  // Find all image link tags wrapper pointing directly to image files inside posts
  var postImages = document.querySelectorAll('.post-body-single a img');
  postImages.forEach(function(img) {
    var parentLink = img.parentElement;
    if (parentLink && parentLink.tagName === 'A') {
      var href = parentLink.getAttribute('href');
      // If link goes directly to an image resource format, strip the link safely
      if (href && (href.match(/\.(jpeg|jpg|gif|png|webp)/i) || href.indexOf('googleusercontent.com') !== -1)) {
        parentLink.replaceWith(img);
      }
    }
  });
});
//

document.addEventListener('DOMContentLoaded', function() {
  // Target Blogger Link List or Page List widgets
  var linkLists = document.querySelectorAll('.Widget.LinkList ul, .Widget.PageList ul');

  linkLists.forEach(function(ul) {
    var items = Array.from(ul.children);
    var currentParent = null;
    var currentSubParent = null;

    items.forEach(function(li) {
      var a = li.querySelector('a');
      if (!a) return;

      var text = a.textContent.trim();

      if (text.startsWith('__')) {
        // Level 2 Sub-item (two underscores)
        a.textContent = text.replace(/^__\s*/, '');
        if (currentSubParent) {
          var subUl = currentSubParent.querySelector('ul');
          if (!subUl) {
            subUl = document.createElement('ul');
            subUl.className = 'sub-dropdown level-2';
            currentSubParent.appendChild(subUl);
          }
          subUl.appendChild(li);
        }
      } else if (text.startsWith('_')) {
        // Level 1 Sub-item (one underscore)
        a.textContent = text.replace(/^_\s*/, '');
        if (currentParent) {
          var mainUl = currentParent.querySelector('ul');
          if (!mainUl) {
            mainUl = document.createElement('ul');
            mainUl.className = 'sub-dropdown level-1';
            currentParent.classList.add('has-dropdown');
            currentParent.appendChild(mainUl);
          }
          mainUl.appendChild(li);
          currentSubParent = li;
        }
      } else {
        // Main level item (no underscore)
        currentParent = li;
        currentSubParent = null;
      }
    });
  });
});
